 "genere": "prevedi",
 "titolo": "Ordinare il codice",
 "consegna": "Leggi ogni pezzo di codice e scrivi cosa restituisce `run()`, senza eseguirlo. Poi confronta con la risposta vera.",
 "modalita": "previsioni",
 "previsioni": [
  {
   "codice": "extends RefCounted

const MAX_HEALTH: int = 100

func run() -> int:
	var current_health: int = MAX_HEALTH - 25
	return current_health
",
   "domanda": "Quanto vale `current_health` alla fine?",
   "spiegazione": "La costante `MAX_HEALTH` definita in maiuscolo vale 100. Sottraendo 25 si ottiene 75."
  },
  {
   "codice": "extends RefCounted

const DEFAULT_SPEED: float = 200.0
const SPEED_MULTIPLIER: float = 1.5

func run() -> float:
	var final_speed: float = DEFAULT_SPEED * SPEED_MULTIPLIER
	return final_speed
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "`DEFAULT_SPEED` (200.0) viene moltiplicato per `SPEED_MULTIPLIER` (1.5). Il risultato è 300.0."
  },
  {
   "codice": "extends RefCounted

const ITEM_DATA: Dictionary = {
	"coin": {"points": 10},
	"gem": {"points": 50}
}

func run() -> int:
	var active_item: String = "gem"
	var item_points: int = ITEM_DATA[active_item]["points"]
	return item_points
",
   "domanda": "Quanto vale `item_points` alla fine?",
   "spiegazione": "`active_item` è "gem". Nel dizionario delle configurazioni `ITEM_DATA`, la chiave "gem" contiene un dizionario con la chiave "points" che vale 50."
  },
  {
   "codice": "extends RefCounted

const BONUS_POINTS: int = 15
const SCORE_MULTIPLIER: int = 2

func run() -> int:
	var base_score: int = 40
	return (base_score + BONUS_POINTS) * SCORE_MULTIPLIER
",
   "domanda": "Che numero restituisce `run()`?",
   "spiegazione": "Le parentesi impongono la precedenza: prima si somma 40 e 15 (ottenendo 55), poi si moltiplica per 2, ottenendo 110."
  }
